1	import { expect, test } from "bun:test";
2	import { runInMicroVm } from "../../src/sandbox/microvm.ts";
3	
4	type ExecResult = { code: number; stdout: string; stderr: string };
5	
6	function makeClient(
7	  execImpl?: (cmd: string[], callIndex: number) => ExecResult | Promise<ExecResult>
8	) {
9	  const events: Array<{
10	    kind: "create" | "write" | "exec" | "stop";
11	    path?: string;
12	    content?: string;
13	    cmd?: string[];
14	    timeoutMs?: number;
15	  }> = [];
16	  const state = { createCalls: 0, stopCalls: 0 };
17	
18	  return {
19	    events,
20	    state,
21	    async create(): Promise<{ id: string }> {
22	      state.createCalls += 1;
23	      events.push({ kind: "create" });
24	      return { id: "vm-1" };
25	    },
26	    async write(_id: string, path: string, content: string): Promise<void> {
27	      events.push({ kind: "write", path, content });
28	    },
29	    async exec(_id: string, cmd: string[], timeoutMs: number): Promise<ExecResult> {
30	      events.push({ kind: "exec", cmd: [...cmd], timeoutMs });
31	      const callIndex = events.filter((e) => e.kind === "exec").length;
32	      if (execImpl) return execImpl(cmd, callIndex);
33	      return { code: 0, stdout: "", stderr: "" };
34	    },
35	    async stop(_id: string): Promise<void> {
36	      state.stopCalls += 1;
37	      events.push({ kind: "stop" });
38	    },
39	  };
40	}
