/**
 * MicroVM runner adapter.
 *
 * Public repo code only ever runs inside an isolated microVM (see docs/DESIGN.md §Security), so this
 * module talks to a VM service through a small client interface instead of to the host. It owns the
 * lifecycle — create, write, clone, run, stop — and never lets a VM outlive a call: `stop` runs on
 * every path, including failures and timeouts.
 */

export interface ExecResult {
  code: number;
  stdout: string;
  stderr: string;
}

export interface MicroVmClient {
  create(): Promise<{ id: string }>;
  exec(id: string, cmd: string[], timeoutMs: number): Promise<ExecResult>;
  write(id: string, path: string, content: string): Promise<void>;
  stop(id: string): Promise<void>;
}

export interface MicroVmRunOptions {
  repoUrl: string;
  command: string[];
  timeoutMs: number;
  files?: Record<string, string>;
}

export interface MicroVmResult extends ExecResult {
  /** True when the clone or the command hit the client's timeout (the client reports code 124). */
  timedOut: boolean;
}

/** Where the repo is cloned inside the VM; also the working directory of `command`. */
export const WORK_DIR = "/work";

/** Exit code a client returns when it killed a call at the deadline. */
const TIMEOUT_CODE = 124;

/** Only https remotes: ssh remotes would need keys in the VM, and file/git remotes point at the host. */
function assertHttpsRepoUrl(repoUrl: string): void {
  let url: URL;
  try {
    url = new URL(repoUrl);
  } catch {
    throw new Error(`repoUrl must be an https URL, got ${JSON.stringify(repoUrl)}`);
  }
  if (url.protocol !== "https:" || url.hostname === "") {
    throw new Error(`repoUrl must be an https URL, got ${JSON.stringify(repoUrl)}`);
  }
}

/** POSIX single-quoting, so an argument survives the shell round-trip unchanged. */
function quoteArg(arg: string): string {
  return `'${arg.replaceAll("'", "'\\''")}'`;
}

/** `exec` has no cwd, so the command goes through a shell that `cd`s into the clone first. */
function commandInWorkDir(command: string[]): string[] {
  return ["sh", "-c", `cd ${WORK_DIR} && ${command.map(quoteArg).join(" ")}`];
}

function toResult(r: ExecResult): MicroVmResult {
  return { code: r.code, stdout: r.stdout, stderr: r.stderr, timedOut: r.code === TIMEOUT_CODE };
}

/**
 * Clone `repoUrl` into a fresh microVM, run `command` in the clone, and destroy the VM.
 *
 * `files` (setup files, rules files) are written to the VM before the clone. A failing clone stops the
 * call: `command` is never run against a repo that isn't there.
 */
export async function runInMicroVm(
  opts: MicroVmRunOptions,
  client: MicroVmClient,
): Promise<MicroVmResult> {
  assertHttpsRepoUrl(opts.repoUrl);

  const { id } = await client.create();
  try {
    for (const [path, content] of Object.entries(opts.files ?? {})) {
      await client.write(id, path, content);
    }

    const clone = await client.exec(
      id,
      ["git", "clone", "--filter=blob:none", opts.repoUrl, WORK_DIR],
      opts.timeoutMs,
    );
    if (clone.code !== 0) return toResult(clone);

    return toResult(await client.exec(id, commandInWorkDir(opts.command), opts.timeoutMs));
  } finally {
    await client.stop(id);
  }
}

