import { describe, expect, test } from "bun:test";

import {
  runInMicroVm,
  WORK_DIR,
  type ExecResult,
  type MicroVmClient,
} from "../src/sandbox/microvm.ts";

type Event =
  | { kind: "create" }
  | { kind: "write"; path: string; content: string }
  | { kind: "exec"; cmd: string[]; timeoutMs: number }
  | { kind: "stop" };

interface FakeClient extends MicroVmClient {
  events: Event[];
  state: { createCalls: number; stopCalls: number };
}

/** A microVM client that records every call and answers `exec` from `execImpl`, keyed by call index. */
function makeClient(
  execImpl?: (cmd: string[], callIndex: number) => ExecResult | Promise<ExecResult>,
  opts: { createFails?: boolean } = {},
): FakeClient {
  const events: Event[] = [];
  const state = { createCalls: 0, stopCalls: 0 };

  return {
    events,
    state,
    async create(): Promise<{ id: string }> {
      state.createCalls += 1;
      events.push({ kind: "create" });
      if (opts.createFails) throw new Error("no capacity");
      return { id: "vm-1" };
    },
    async write(_id: string, path: string, content: string): Promise<void> {
      events.push({ kind: "write", path, content });
    },
    async exec(_id: string, cmd: string[], timeoutMs: number): Promise<ExecResult> {
      events.push({ kind: "exec", cmd: [...cmd], timeoutMs });
      const callIndex = events.filter((e) => e.kind === "exec").length;
      return execImpl ? await execImpl(cmd, callIndex) : { code: 0, stdout: "", stderr: "" };
    },
    async stop(_id: string): Promise<void> {
      state.stopCalls += 1;
      events.push({ kind: "stop" });
    },
  };
}

const execs = (client: FakeClient) => client.events.filter((e) => e.kind === "exec");
const kinds = (client: FakeClient) => client.events.map((e) => e.kind);

const REPO = "https://github.com/owner/repo.git";

// ---------- URL guard ----------

describe("repoUrl guard", () => {
  const rejected = [
    "[REDACTED_EMAIL]:owner/repo.git",
    "ssh://[REDACTED_EMAIL]/owner/repo.git",
    "http://github.com/owner/repo.git",
    "git://github.com/owner/repo.git",
    "file:///srv/repo.git",
    "/srv/repo.git",
    "github.com/owner/repo",
    "not a url",
    "",
  ];

  for (const repoUrl of rejected) {
    test(`rejects ${repoUrl || "<empty>"} before touching the client`, async () => {
      const client = makeClient();

      await expect(
        runInMicroVm({ repoUrl, command: ["true"], timeoutMs: 5000 }, client),
      ).rejects.toThrow(/https/);

      expect(client.state.createCalls).toBe(0);
      expect(client.state.stopCalls).toBe(0);
      expect(client.events).toEqual([]);
    });
  }

  test("rejects the URL before writing, even when files are supplied", async () => {
    const client = makeClient();

    await expect(
      runInMicroVm(
        { repoUrl: "[REDACTED_EMAIL]:owner/repo.git", command: ["ls"], timeoutMs: 5000, files: { "a": "b" } },
        client,
      ),
    ).rejects.toThrow();

    expect(client.events).toEqual([]);
  });
});

// ---------- happy path ----------

describe("happy path", () => {
  test("creates, writes files, clones, runs the command in /work, and stops", async () => {
    const client = makeClient((_cmd, callIndex) =>
      callIndex === 1
        ? { code: 0, stdout: "clone ok", stderr: "" }
        : { code: 0, stdout: "command out", stderr: "" },
    );

    const result = await runInMicroVm(
      {
        repoUrl: REPO,
        command: ["bun", "test", "tests/one.test.ts"],
        timeoutMs: 30_000,
        files: { "README.md": "hello", "src/main.ts": "console.log('hi')" },
      },
      client,
    );

    expect(result).toEqual({ code: 0, stdout: "command out", stderr: "", timedOut: false });
    expect(client.state).toEqual({ createCalls: 1, stopCalls: 1 });
    expect(kinds(client)).toEqual(["create", "write", "write", "exec", "exec", "stop"]);

    const [clone, run] = execs(client);
    expect(clone?.cmd).toEqual(["git", "clone", "--filter=blob:none", REPO, WORK_DIR]);
    expect(clone?.timeoutMs).toBe(30_000);
    expect(run?.timeoutMs).toBe(30_000);

    // Both calls get the caller's deadline; the command runs inside the clone.
    expect(run?.cmd[0]).toBe("sh");
    expect(run?.cmd[1]).toBe("-c");
    expect(run?.cmd[2]).toBe(`cd ${WORK_DIR} && 'bun' 'test' 'tests/one.test.ts'`);

    expect(client.events.filter((e) => e.kind === "write")).toEqual([
      { kind: "write", path: "README.md", content: "hello" },
      { kind: "write", path: "src/main.ts", content: "console.log('hi')" },
    ]);
  });

  test("quotes arguments so spaces and quotes survive the shell round-trip", async () => {
    const client = makeClient();

    await runInMicroVm(
      { repoUrl: REPO, command: ["printf", "%s\n", "it's a test"] , timeoutMs: 5000 },
      client,
    );

    expect(execs(client)[1]?.cmd[2]).toBe(`cd ${WORK_DIR} && 'printf' '%s\\n' 'it'\\''s a test'`);
  });

  test("does not call write when no files are given", async () => {
    const client = makeClient();

    await runInMicroVm({ repoUrl: REPO, command: ["ls"], timeoutMs: 5000 }, client);

    expect(kinds(client)).toEqual(["create", "exec", "exec", "stop"]);
    expect(client.events.filter((e) => e.kind === "write")).toEqual([]);
    expect(client.state.createCalls).toBe(1);
  });
});

// ---------- failures still stop the VM ----------

describe("failures", () => {
  test("returns the clone failure and never runs the command", async () => {
    const client = makeClient((_cmd, callIndex) =>
      callIndex === 1 ? { code: 128, stdout: "", stderr: "fatal: repo not found" } : { code: 0, stdout: "no", stderr: "" },
    );

    const result = await runInMicroVm({ repoUrl: REPO, command: ["false"], timeoutMs: 5000 }, client);

    expect(result).toEqual({ code: 128, stdout: "", stderr: "fatal: repo not found", timedOut: false });
    expect(kinds(client)).toEqual(["create", "exec", "stop"]);
    expect(client.state.stopCalls).toBe(1);
  });

  test("returns the command failure and still stops", async () => {
    const client = makeClient((_cmd, callIndex) =>
      callIndex === 1 ? { code: 0, stdout: "clone ok", stderr: "" } : { code: 1, stdout: "out", stderr: "boom" },
    );

    const result = await runInMicroVm({ repoUrl: REPO, command: ["false"], timeoutMs: 5000 }, client);

    expect(result).toEqual({ code: 1, stdout: "out", stderr: "boom", timedOut: false });
    expect(client.state.stopCalls).toBe(1);
    expect(kinds(client)).toEqual(["create", "exec", "exec", "stop"]);
  });

  test("reports a command timeout as timedOut with code 124", async () => {
    const client = makeClient((_cmd, callIndex) =>
      callIndex === 1 ? { code: 0, stdout: "clone ok", stderr: "" } : { code: 124, stdout: "partial", stderr: "killed" },
    );

    const result = await runInMicroVm({ repoUrl: REPO, command: ["sleep", "600"], timeoutMs: 100 }, client);

    expect(result).toEqual({ code: 124, stdout: "partial", stderr: "killed", timedOut: true });
    expect(client.state.stopCalls).toBe(1);
    expect(kinds(client)).toEqual(["create", "exec", "exec", "stop"]);
  });

  test("reports a clone timeout as timedOut with code 124 and runs no command", async () => {
    const client = makeClient(() => ({ code: 124, stdout: "", stderr: "timed out cloning" }));

    const result = await runInMicroVm({ repoUrl: REPO, command: ["true"], timeoutMs: 100 }, client);

    expect(result).toEqual({ code: 124, stdout: "", stderr: "timed out cloning", timedOut: true });
    expect(kinds(client)).toEqual(["create", "exec", "stop"]);
    expect(client.state.stopCalls).toBe(1);
  });

  test("stops the VM when exec rejects, and lets the error through", async () => {
    const client = makeClient(async (_cmd, callIndex) => {
      if (callIndex === 1) return { code: 0, stdout: "clone ok", stderr: "" };
      throw new Error("vm exploded");
    });

    await expect(
      runInMicroVm({ repoUrl: REPO, command: ["false"], timeoutMs: 5000 }, client),
    ).rejects.toThrow("vm exploded");

    expect(client.state.stopCalls).toBe(1);
    expect(kinds(client)).toEqual(["create", "exec", "exec", "stop"]);
  });

  test("stops the VM when the clone rejects", async () => {
    const client = makeClient(async () => {
      throw new Error("clone transport died");
    });

    await expect(
      runInMicroVm({ repoUrl: REPO, command: ["true"], timeoutMs: 5000 }, client),
    ).rejects.toThrow("clone transport died");

    expect(client.state.stopCalls).toBe(1);
    expect(kinds(client)).toEqual(["create", "exec", "stop"]);
  });

  test("does not create a VM when create itself rejects, so there is nothing to stop", async () => {
    const client = makeClient(undefined, { createFails: true });

    await expect(
      runInMicroVm({ repoUrl: REPO, command: ["true"], timeoutMs: 5000 }, client),
    ).rejects.toThrow("no capacity");

    expect(client.state).toEqual({ createCalls: 1, stopCalls: 0 });
    expect(client.events).toEqual([{ kind: "create" }]);
  });
});

describe("file writes", () => {
  test("a failing write still stops the VM and skips the clone", async () => {
    const client = makeClient();
    client.write = async (_id: string, path: string, content: string) => {
      client.events.push({ kind: "write", path, content });
      throw new Error("disk full");
    };

    await expect(
      runInMicroVm({ repoUrl: REPO, command: ["true"], timeoutMs: 5000, files: { "a.txt": "a" } }, client),
    ).rejects.toThrow("disk full");

    expect(kinds(client)).toEqual(["create", "write", "stop"]);
    expect(client.state.stopCalls).toBe(1);
  });

  test("writes in insertion order, one call per file", async () => {
    const client = makeClient();

    await runInMicroVm(
      { repoUrl: REPO, command: ["true"], timeoutMs: 5000, files: { "z.txt": "1", "a.txt": "2", "m/x.txt": "" } },
      client,
    );

    expect(client.events.filter((e) => e.kind === "write")).toEqual([
      { kind: "write", path: "z.txt", content: "1" },
      { kind: "write", path: "a.txt", content: "2" },
      { kind: "write", path: "m/x.txt", content: "" },
    ]);
  });
});

