input.new_string:
test("quotes each argument so nothing is split, expanded or injected by the shell", async () => {
  const client = makeClient();
  const command = ["printf", "%s|", "two  spaces", "it's a test", "$HOME", "*; rm -rf /"];

  await runInMicroVm({ repoUrl: REPO, command, timeoutMs: 5000 }, client);

  const script = execs(client)[1]!.cmd[2]!;
  expect(script).toBe(`cd ${WORK_DIR} && 'printf' '%s|' 'two  spaces' 'it'\\''s a test' '$HOME' '*'\\''; rm -rf /'`);

  // Round-trip the generated string through a real shell (minus the `cd`, which needs the VM's /work):
  // every argument must arrive whole and unexpanded.
  const shell = Bun.spawnSync(["sh", "-c", script.replace(`cd ${WORK_DIR} && `, "")]);
  expect(shell.exitCode).toBe(0);
  expect(shell.stdout.toString()).toBe("two  spaces|it's a test|$HOME|*; rm -rf /|");
});

